local CommonChooseRewardPopup = Class("CommonChooseRewardPopup")
local CellPath = "Game.Behaviours.CommonChooseRewardCell"
local GoodsNodeMBPath = 'Game.Behaviours.GoodNodeMB'
local ReverseScaleType = typeof(CS.Game.Native.Common.ReverseScale)
---@type Engine.Lib.KTool
local KTool         = CS.Engine.Lib.KTool

function CommonChooseRewardPopup:__init()
    self.rewards = {}
end

function CommonChooseRewardPopup:__delete()
    self.rewards = nil
    self.controller = nil
end

function CommonChooseRewardPopup:Awake()
    self:AddUIClick()
    self:InitComponent()
end

function CommonChooseRewardPopup:InitComponent()
    CfUtils.SetActive(self.Content.gameObject,false)
    CfUtils.SetActive(self.RewardIndo.gameObject,false)
end

function CommonChooseRewardPopup:AddUIClick()
    SetButtonAction(self.ClickClose, Bind(self,self.OnCloseBtnClick))
    SetButtonAction(self.BtnClose, Bind(self,self.OnCloseBtnClick))
    SetButtonAction(self.BtnChoose, Bind(self,self.OnBtnChooseClick))
end

function CommonChooseRewardPopup:OnFocus(focus)

end

function CommonChooseRewardPopup:OnShow()
    self:RefreshShow()
end

function CommonChooseRewardPopup:OnInitialize()
    local parameters = self.controller.Argument.parameters
    if parameters and isSet(parameters,"rewards") then
        self.rewards = parameters.rewards
    end
end

function CommonChooseRewardPopup:OnFinalize()

end

function CommonChooseRewardPopup:RefreshShow()
    local count = table.count(self.rewards)
    if count > 0 then
        self:InitGridView(count)
    end
end

function CommonChooseRewardPopup:InitGridView(count)
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(count, Bind(self, self.OnRefreshIndex))
    else
        GameUtils.ReloadData(self.ListView, count)
    end
end

function CommonChooseRewardPopup:OnRefreshIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("CommonChooseRewardCell")
    if isNotNull(cell) then
        local scr = CfUtils.GetLuaScr(cell.gameObject, CellPath)
        if scr then
            local data = self.rewards[index + 1]
            scr:SetCellCallBack(Bind(self,self.OnCellClick))
            scr:RefreshShow(data,index + 1)
            if isNotNull(self.curIndex) and self.curIndex == index + 1 then
                scr:SetSelectState(true)
            else
                scr:SetSelectState(false)
            end
        end
    end
    return cell
end

function CommonChooseRewardPopup:OnCellClick(index)
    if isNotNull(self.curIndex) and self.curIndex == index then
        return
    end

    local lastIndex = self.curIndex
    if isNotNull(lastIndex) then
        local cellItem = self.ListView:GetShownItemByItemIndex(lastIndex - 1)
        if isNotNull(cellItem) then
            local env = CfUtils.GetLuaScr(cellItem, CellPath)
            if not isNull(env) then
                env:SetSelectState(false)
            end
        end
    end

    self.curIndex = index
    self:RefreshInfoShow(self.rewards[index])
    CfUtils.SetActive(self.RewardIndo.gameObject,true)
end

function CommonChooseRewardPopup:RefreshInfoShow(data)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
    if not isNull(goodsVo) then
        CfUtils.FillText(self.InfoTextDesc,goodsVo.name)
        CfUtils.FillText(self.TextDesc, goodsVo.desc)
        local goodsType = GoodsUtils.GetIdType(data.goodsId)
        if goodsType == Constants.IDType.GoodsUsable then
            CfUtils.SetActive(self.BtnCheck, true)
            SetButtonAction(self.BtnCheck, function()
                GameUtils.ShowCommonGoodsTipsBoard(self.BtnCheck, data.goodsId, data.num)
            end)
        else
            CfUtils.SetActive(self.BtnCheck, false)
        end

        if isNull(self.GoodNode) then
            self.GoodNode = self.GoodNodeStub:InstantiatePrefab("GoodNode")
            local rect = self.GoodNode.gameObject:GetComponent("RectTransform")
            rect.pivot = Vector2.New(0.5, 0.5)
            rect.anchoredPosition = Vector3.New(0, 0, 0)
            rect.anchorMax = Vector2.New(0.5, 0.5)
            rect.anchorMin = Vector2.New(0.5, 0.5)
            CfUtils.SetActive(self.GoodNode.gameObject, true)

            ---存在该节点将 父节点的缩放丢到该节点上
            ---@type Game.Native.Common.ReverseScale
            local reScaleComp = KTool.GetComponent(self.GoodNode.gameObject, ReverseScaleType)
            if isNotNull(reScaleComp) then
                reScaleComp.scale = 1
                reScaleComp:ResetScale()
            end
        end

        if isNull(self.goodNodeMB) then
            self.goodNodeMB = CfUtils.GetLuaScr(self.GoodNode, GoodsNodeMBPath)
        end

        self.goodNodeMB:Reload({ isShowNo = false , goodsId = data.goodsId, num = data.num, text = "x"..data.num})
        CfUtils.SetActive(self.BtnRewardNode.gameObject,false)
        CfUtils.SetActive(self.Content.gameObject,true)

        local haveNum = GoodsUtils.GetThingNo(data.goodsId)
        CfUtils.FillText(self.TextNumber, haveNum)
    end
end

function CommonChooseRewardPopup:OnCloseBtnClick()
    UIModule.CloseDialog(self.controller)
end

function CommonChooseRewardPopup:OnBtnChooseClick()
    if not isNull(self.curIndex) then
        local data = self.rewards[self.curIndex]
        if data.isLockItem then
            GameUtils.Toast(data.SelectDesc)
            return
        end

        Events.Broadcast(Constants.EventNames.CommonChooseRewardFinish, data, self.curIndex)
        self:OnCloseBtnClick()
    end
end

return CommonChooseRewardPopup